// Iteramos sobre todos los items que entran al nodo
for (const item of $input.all()) {

  // --- CORRECCIÓN AQUÍ ---
  // El nodo de IA a veces devuelve el texto directo o anidado en 'parts'.
  // Vamos a intentar obtenerlo de ambas formas para que no falle.

  let texto = "";
  const rawContent = item.json.content;

  if (rawContent && typeof rawContent === 'object' && rawContent.parts && rawContent.parts[0]) {
    // Caso: Estructura anidada (La que tienes en tu imagen)
    texto = rawContent.parts[0].text || "";
  } else if (typeof rawContent === 'string') {
    // Caso: Texto directo
    texto = rawContent;
  } else {
    // Caso: Fallback por si la estructura cambia
    texto = JSON.stringify(rawContent) || "";
  }
  // -----------------------

  // 1. HELPER DE EXTRACCIÓN
  const extraer = (clave) => {
    const regex = new RegExp(`- ${clave}:\\s*(.*)`, 'i');
    const match = texto.match(regex);
    return match ? match[1].trim() : null;
  };

  // 2. HELPER DE PARSEO DE MONTO (reutilizable)
  const parsearMonto = (montoString) => {
    if (!montoString) return 0;
    let soloNumeros = montoString.replace(/[^0-9.,]/g, '');
    // Si tiene punto Y coma, la coma es separador de miles → eliminarla
    if (soloNumeros.includes('.') && soloNumeros.includes(',')) {
      soloNumeros = soloNumeros.replace(/,/g, '');
    }
    // Si solo tiene coma, es decimal → reemplazar por punto
    else if (soloNumeros.includes(',')) {
      soloNumeros = soloNumeros.replace(',', '.');
    }
    return parseFloat(soloNumeros) || 0;
  };

  // 3. HELPER DE EXTRACCIÓN DE DATOS COMUNES DE PAGO
  const extraerDatosPago = () => {
    const montoString = extraer("Monto");
    item.json.monto_texto = montoString;
    item.json.monto_numero = parsearMonto(montoString);
    item.json.moneda = extraer("Moneda");
    item.json.metodo_pago = extraer("Método de Pago");
    item.json.emisor = extraer("Emisor");
    item.json.destinatario = extraer("Destinatario");
    item.json.fecha = extraer("Fecha");
    item.json.id_transaccion = extraer("ID Transacción");
  };

  // 4. LÓGICA DE CLASIFICACIÓN
  // Ahora 'texto' ya es un String seguro, por lo que .includes() funcionará

  if (texto.includes("Etiqueta: Pago de pedido")) {
    // CASO 2A: Comprobante de pago válido - PEDIDO
    item.json.es_pago = true;
    item.json.tipo_solicitud = "finanzas";
    item.json.tipo_pago = "pedido";
    extraerDatosPago();

  } else if (texto.includes("Etiqueta: Pago de plan nuevo")) {
    // CASO 2B: Comprobante de pago válido - PLAN NUEVO
    item.json.es_pago = true;
    item.json.tipo_solicitud = "finanzas";
    item.json.tipo_pago = "plan_nuevo";
    extraerDatosPago();

  } else if (texto.includes("Etiqueta: Pago de reconsumo")) {
    // CASO 2C: Comprobante de pago válido - RECONSUMO
    item.json.es_pago = true;
    item.json.tipo_solicitud = "finanzas";
    item.json.tipo_pago = "reconsumo";
    extraerDatosPago();

  } else if (texto.includes("Etiqueta: Reclamo de Calidad")) {
    // CASO 1: Foto de producto/comida → va a soporte pero SIN pedir comprobante
    item.json.es_pago = false;
    item.json.tipo_solicitud = "soporte";
    item.json.es_reclamo_calidad = true;  // Flag para identificar el subtipo

    const matchDesc = texto.match(/Descripción:\s*(.*)/is);
    item.json.mensaje_problema = matchDesc ? matchDesc[1].trim() : "Foto de producto recibida";

  } else if (texto.includes("Etiqueta: Atención al Cliente")) {
    // CASO 3: Otros casos de soporte
    item.json.es_pago = false;
    item.json.tipo_solicitud = "soporte";
    item.json.es_reclamo_calidad = false;

    const matchDesc = texto.match(/Descripción:\s*(.*)/is);
    item.json.mensaje_problema = matchDesc ? matchDesc[1].trim() : texto;

  } else {
    // Fallback: Caso desconocido
    item.json.es_pago = false;
    item.json.tipo_solicitud = "desconocido";
    item.json.es_reclamo_calidad = false;
    item.json.error_raw = texto;
  }
}

return $input.all();

